    ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
    MON = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
    ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
    FULL = dict([('TL', 'Türk Lirası'), ('USD', 'Dolar'), ('EUR', 'Euro'), ('GBP', 'İngiliz Sterlini')])
    UNIT = dict([('TL', ['lira', 'kuruş']), ('USD', ['Dolar', 'sent']), ('EUR', ['Euro', 'sent']), ('GBP', ['İngiliz Sterlini', 'peni'])])
    SUF = dict([('Lirası', AP + 'dır'), ('Dolar', AP + 'dır'), ('Euro', AP + 'dur'), ('Sterlini', AP + 'dir'), ('kuruş', 'tur'), ('sent', 'tir'), ('peni', 'dir')])
    YS = ['dir', 'dir', 'dir', 'tür', 'tür', 'tir', 'dır', 'dir', 'dir', 'dur']
    TS = ['dir', 'dur', 'dir', 'dur', 'tır', 'dir', 'tır', 'tir', 'dir', 'dır']
