        v = vars.get(k)
        return '' if v is None else str(v).strip()
    def dig(s):
        return ' '.join([DW[int(ch)] for ch in str(s) if ch.isdigit()])
    def three(n):
        p = []
        h = n // 100
        r = n % 100
        if h:
            p.append('yüz' if h == 1 else ONES[h] + ' yüz')
        if r // 10:
            p.append(TENS[r // 10])
        if r % 10:
            p.append(ONES[r % 10])
        return ' '.join(p)
    def words(n):
        n = int(n)
        if n == 0:
            return 'sıfır'
        p = []
        for val, nm in [(1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')]:
            q = n // val
            if q:
                p.append('bin' if (val == 1000 and q == 1) else three(q) + ' ' + nm)
                n = n % val
        if n:
            p.append(three(n))
        return ' '.join(p)
    def amt(x, cur):
        c = int(round(abs(float(x)) * 100))
        ma = c // 100
        mi = c % 100
        if mi == 0:
            return words(ma) + ' ' + FULL[cur]
        if ma == 0:
            return words(mi) + ' ' + UNIT[cur][1]
        return words(ma) + ' ' + UNIT[cur][0] + ' ' + words(mi) + ' ' + UNIT[cur][1]
    def cop(ph):
        return ph + SUF.get(ph.split()[-1], AP + 'dir')
    def num(v):
