            return ''
        return str(t[0]) + ' ' + MON[t[1]] + ' ' + str(t[2])
    def dcop(s):
        y = dparse(s)[2]
        sf = YS[y % 10] if y % 10 else TS[(y // 10) % 10]
        return dsay(s) + AP + sf
