                say = 'Bu isimde bir kartınız bulunmuyor. Kartlarınız: ' + lst + '. Hangi kartınızın borcunu öğrenmek istersiniz?'
            else:
                say = 'Söylediğiniz bilgilere uyan bir kartınız bulunmuyor. ' + question(cand)
        elif len(new) == 1:
